// In the original spec, `is_2_pow` is a spec-only helper.
// Here we provide a normal Rust implementation for completeness.
pub fn is_2_pow(n: i128) -> bool {
    if n <= 0 {
        return false;
    }
    // Power of two iff exactly one bit set.
    (n & (n - 1)) == 0
}

/// Returns the lower-bound insertion index of `x` in the sorted range `a[lo..hi)`.
/// That is, returns `k` with `lo <= k <= hi` such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
///
/// Assumes `a[lo..hi)` is sorted in nondecreasing order and indices are valid.
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());

    // Standard lower_bound binary search on [lo, hi)
    let mut left = lo;
    let mut right = hi;
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

